  "witnessCode": "import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import x from '../index.js';

test('keepQueryParameters single element', () => {
  const url = 'http://example.com?keep=this&drop=that';
  const options = { keepQueryParameters: ['keep'] };
  const result = x(url, options);
  // Expected result when keepQueryParameters length is 1: only that parameter remains
  assert.strictEqual(result, 'http://example.com/?keep=this');
});"
